import sys

MOD = 998244353
G = 3


def ntt(a, invert):
    n = len(a)

    j = 0
    for i in range(1, n):
        bit = n >> 1
        while j & bit:
            j ^= bit
            bit >>= 1
        j ^= bit
        if i < j:
            a[i], a[j] = a[j], a[i]

    length = 2
    while length <= n:
        wlen = pow(G, (MOD - 1) // length, MOD)
        if invert:
            wlen = pow(wlen, MOD - 2, MOD)

        half = length >> 1
        for i in range(0, n, length):
            w = 1
            end = i + half
            for j in range(i, end):
                u = a[j]
                v = a[j + half] * w % MOD
                a[j] = (u + v) % MOD
                a[j + half] = (u - v) % MOD
                w = w * wlen % MOD
        length <<= 1

    if invert:
        inv_n = pow(n, MOD - 2, MOD)
        for i in range(n):
            a[i] = a[i] * inv_n % MOD


def convolution(a, b):
    if not a or not b:
        return []

    if min(len(a), len(b)) <= 32:
        res = [0] * (len(a) + len(b) - 1)
        for i, x in enumerate(a):
            if x:
                for j, y in enumerate(b):
                    res[i + j] = (res[i + j] + x * y) % MOD
        return res

    need = len(a) + len(b) - 1
    size = 1
    while size < need:
        size <<= 1

    fa = a + [0] * (size - len(a))
    fb = b + [0] * (size - len(b))
    ntt(fa, False)
    ntt(fb, False)

    for i in range(size):
        fa[i] = fa[i] * fb[i] % MOD

    ntt(fa, True)
    return fa[:need]


def main():
    input = sys.stdin.readline
    n = int(input())
    s = input().strip()
    m = 2 * n

    fact = [1] * (n + 1)
    for i in range(1, n + 1):
        fact[i] = fact[i - 1] * i % MOD

    invfact = [1] * (n + 1)
    invfact[n] = pow(fact[n], MOD - 2, MOD)
    for i in range(n, 0, -1):
        invfact[i - 1] = invfact[i] * i % MOD

    # Every feasible internal cut (W-prefix count >= B-prefix count).
    events = []
    w = b = 0
    for i, ch in enumerate(s):
        if ch == 'W':
            w += 1
        else:
            b += 1

        if i != m - 1 and w >= b:
            events.append((w, b, False))

    # The final cut is always included as the terminal point.
    events.append((n, n, True))
    q = len(events)

    # acc[k] stores contributions from already processed selected cuts.
    acc = [0] * q
    dp = [0] * q

    # The initial segment starts at (0, 0), contributing fact[w].
    for i, (w_i, _, _) in enumerate(events):
        acc[i] = fact[w_i]

    internal_count = q - 1

    def add_contributions(left, mid, right):
        sources = [0] * (n + 1)
        min_b = n + 1
        max_b = -1

        for i in range(left, min(mid, internal_count)):
            value = dp[i]
            if value:
                bi = events[i][1]
                sources[bi] = (sources[bi] + value) % MOD
                if bi < min_b:
                    min_b = bi
                if bi > max_b:
                    max_b = bi

        if max_b < 0:
            return

        min_w = n + 1
        max_w = -1
        for i in range(mid, right):
            wi = events[i][0]
            if wi < min_w:
                min_w = wi
            if wi > max_w:
                max_w = wi

        if max_w < min_b:
            return

        source = sources[min_b:max_b + 1]
        kernel = fact[:max_w - min_b + 1]
        conv = convolution(source, kernel)

        for i in range(mid, right):
            wi = events[i][0]
            idx = wi - min_b
            if 0 <= idx < len(conv):
                acc[i] = (acc[i] + conv[idx]) % MOD

    sys.setrecursionlimit(1_000_000)

    def cdq(left, right):
        if right - left == 1:
            w_i, b_i, is_final = events[left]
            value = acc[left] * invfact[w_i - b_i] % MOD

            if is_final:
                dp[left] = value
            else:
                # Inclusion-exclusion contributes a minus sign for every
                # selected internal cut.
                dp[left] = (-value) % MOD
            return

        mid = (left + right) >> 1
        cdq(left, mid)
        add_contributions(left, mid, right)
        cdq(mid, right)

    cdq(0, q)
    print(dp[-1] % MOD)


if __name__ == "__main__":
    main()

import sys
from collections import defaultdict

def solve():
    input = sys.stdin.buffer.readline

    N, M, Q = map(int, input().split())

    groups = defaultdict(list)
    undirected = {}

    for i in range(1, M + 1):
        s, t = map(int, input().split())

        if s < t:
            left, right = s, t
        else:
            left, right = t, s

        # At each endpoint, classify the other endpoint by its side.
        groups[(s, 0 if t < s else 1)].append((i, t))
        groups[(t, 0 if s < t else 1)].append((i, s))

        key = (left, right)
        if key in undirected:
            j = undirected[key]
            # Opposite directions on the same path are contradictory.
            # Store this conflict separately using the smaller index later.
            undirected[key] = (j, i)
        else:
            undirected[key] = i

    # g[i] = the smallest j > i such that people i and j conflict.
    INF = M + 1
    g = [INF] * (M + 1)

    # Conflicts caused by two roads sharing an endpoint and lying on the same side.
    for arr in groups.values():
        arr.sort()
        k = len(arr)

        for p in range(k):
            i, other = arr[p]

            q = p + 1
            if q < k and arr[q][1] == other:
                q += 1

            if q < k:
                j = arr[q][0]
                if j < g[i]:
                    g[i] = j

    # Conflicts caused by the two opposite directions of the same undirected path.
    for value in undirected.values():
        if isinstance(value, tuple):
            a, b = value
            if a > b:
                a, b = b, a
            if b < g[a]:
                g[a] = b

    # f[l] = smallest right endpoint of a conflicting pair entirely contained
    # in [l, M].
    f = [INF] * (M + 2)
    for i in range(M, 0, -1):
        f[i] = min(f[i + 1], g[i])

    out = []
    for _ in range(Q):
        l, r = map(int, input().split())
        out.append("No" if f[l] <= r else "Yes")

    sys.stdout.write("\n".join(out))

if __name__ == "__main__":
    solve()

from typing import List


class Solution:
    def maxProduct(self, nums: List[int], k: int, limit: int) -> int:
        n = len(nums)
        max_sum = 12 * n

        if abs(k) > max_sum:
            return -1

        offset = max_sum
        target_bit = 1 << (k + offset)
        overflow = limit + 1

        # states[product] = [bitmask for even-length subsequences,
        #                    bitmask for odd-length subsequences]
        states = {}

        for x in nums:
            snapshot = [
                (product, masks[0], masks[1])
                for product, masks in states.items()
            ]

            # Start a new subsequence containing only x.
            single_product = x if x <= limit else overflow
            masks = states.setdefault(single_product, [0, 0])
            masks[1] |= 1 << (offset + x)

            # Extend all subsequences formed before this element.
            for product, even_mask, odd_mask in snapshot:
                if x == 0:
                    new_product = 0
                elif product == overflow or product * x > limit:
                    new_product = overflow
                else:
                    new_product = product * x

                target = states.setdefault(new_product, [0, 0])

                if even_mask:
                    # Even index in the subsequence contributes +x.
                    target[1] |= even_mask << x

                if odd_mask:
                    # Odd index in the subsequence contributes -x.
                    target[0] |= odd_mask >> x

        for product in range(limit, -1, -1):
            masks = states.get(product)
            if masks is not None and (masks[0] & target_bit or masks[1] & target_bit):
                return product

        return -1

import sys

def solve_case(n, k, cakes):
    need = 2 * k

    best = []
    for i, (x, y, z) in enumerate(cakes):
        vals = (x, y, z)
        label = max(range(3), key=lambda d: vals[d])
        best.append((vals[label], label, i))

    best.sort(reverse=True)
    selected = best[:need]
    selected_set = {i for _, _, i in selected}

    base_value = sum(v for v, _, _ in selected)
    base_parity = 0
    for _, label, _ in selected:
        base_parity ^= 1 << label

    if base_parity == 0:
        return base_value

    # For each parity vector corresponding to changing between two labels:
    # 0 -> labels (0,1), 1 -> (0,2), 2 -> (1,2)
    pair_index = {(0, 1): 0, (0, 2): 1, (1, 2): 2}
    operations = [[] for _ in range(3)]

    # Selected items grouped by their baseline label.
    selected_by_label = [[] for _ in range(3)]
    for value, label, idx in selected:
        selected_by_label[label].append((value, idx))
    for d in range(3):
        selected_by_label[d].sort(reverse=True)
        selected_by_label[d] = selected_by_label[d][:8]

    # Unselected items grouped by their value for each label.
    unselected_by_label = [[] for _ in range(3)]
    for i, vals in enumerate(cakes):
        if i not in selected_set:
            for d in range(3):
                unselected_by_label[d].append((vals[d], i))
    for d in range(3):
        unselected_by_label[d].sort(reverse=True)
        unselected_by_label[d] = unselected_by_label[d][:8]

    # One operation: recolor a selected item.
    for value, label, idx in selected:
        vals = cakes[idx]
        for other in range(3):
            if other == label:
                continue
            a, b = sorted((label, other))
            p = pair_index[(a, b)]
            loss = value - vals[other]
            operations[p].append((loss, idx, -1))

    # One operation: replace a selected item by an unselected item.
    for a, b in ((0, 1), (0, 2), (1, 2)):
        p = pair_index[(a, b)]

        for value, idx in selected_by_label[a]:
            for new_value, new_idx in unselected_by_label[b]:
                operations[p].append((value - new_value, idx, new_idx))

        for value, idx in selected_by_label[b]:
            for new_value, new_idx in unselected_by_label[a]:
                operations[p].append((value - new_value, idx, new_idx))

        operations[p].sort()
        operations[p] = operations[p][:80]

    # Keep only the best recolor candidates too; the swap candidates above
    # are already bounded and included in the same lists.
    for p in range(3):
        operations[p].sort()
        operations[p] = operations[p][:100]

    target = base_parity
    answer_loss = 10**30

    # One operation.
    for p in range(3):
        parity = (1 << ((0, 1, 2)[p // 2])) if False else None

    vector_masks = [0b011, 0b101, 0b110]

    for p in range(3):
        if vector_masks[p] == target:
            for loss, _, _ in operations[p]:
                answer_loss = min(answer_loss, loss)

    # Two operations.
    for p in range(3):
        for q in range(p, 3):
            if (vector_masks[p] ^ vector_masks[q]) != target:
                continue
            for loss1, rem1, add1 in operations[p]:
                for loss2, rem2, add2 in operations[q]:
                    used1 = {rem1}
                    if add1 != -1:
                        used1.add(add1)
                    used2 = {rem2}
                    if add2 != -1:
                        used2.add(add2)
                    if used1.isdisjoint(used2):
                        answer_loss = min(answer_loss, loss1 + loss2)

    return base_value - answer_loss


