from typing import List


class Solution:
    def minimumCost(self, nums: List[int], cost: List[int], k: int) -> int:
        n = len(nums)

        prefix_nums = [0] * (n + 1)
        prefix_cost = [0] * (n + 1)

        for i in range(n):
            prefix_nums[i + 1] = prefix_nums[i] + nums[i]
            prefix_cost[i + 1] = prefix_cost[i] + cost[i]

        total_cost = prefix_cost[n]
        dp = [0] + [float("inf")] * n

        for r in range(1, n + 1):
            current_prefix_num = prefix_nums[r]
            current_prefix_cost = prefix_cost[r]

            for l in range(1, r + 1):
                previous_cost = prefix_cost[l - 1]
                segment_cost = current_prefix_num * (
                    current_prefix_cost - previous_cost
                )

                value = dp[l - 1] + segment_cost

                if l > 1:
                    value += k * (total_cost - previous_cost)

                if value < dp[r]:
                    dp[r] = value

        return dp[n] + k * total_cost

import sys

def solve():
    input = sys.stdin.readline

    n = int(input())
    s = input().strip()
    t = input().strip()

    mapping = [-1] * 26
    present = [False] * 26

    for a, b in zip(s, t):
        x = ord(a) - ord('a')
        y = ord(b) - ord('a')
        present[x] = True

        if mapping[x] == -1:
            mapping[x] = y
        elif mapping[x] != y:
            print(-1)
            return

    operations = sum(
        1 for x in range(26)
        if present[x] and mapping[x] != x
    )

    state = [0] * 26
    cycles = 0

    def dfs(v):
        nonlocal cycles
        state[v] = 1
        u = mapping[v]

        if u != -1 and mapping[u] != -1:
            if state[u] == 0:
                dfs(u)
            elif state[u] == 1:
                cycles += 1

        state[v] = 2

    for x in range(26):
        if present[x] and mapping[x] != x and state[x] == 0:
            dfs(x)

    if cycles > 0 and len(set(t)) == 26:
        print(-1)
    else:
        print(operations + cycles)

