    solve()

import sys
from math import comb

MOD = 998244353

def solve():
    input = sys.stdin.readline
    N, K = map(int, input().split())
    A = list(map(int, input().split()))

    coeff = [
        (comb(K, t) if t % 2 == 0 else -comb(K, t)) % MOD
        for t in range(K + 1)
    ]

    sums = [0] * (K + 1)
    sums[0] = 1  # P_0^0
    prefix = 0
    answer = 0

    for a in A:
        prefix = (prefix + a) % MOD

        powers = [1] * (K + 1)
        for t in range(1, K + 1):
            powers[t] = powers[t - 1] * prefix % MOD

        for t in range(K + 1):
            answer = (
                answer
                + coeff[t] * powers[K - t] % MOD * sums[t]
            ) % MOD

        for t in range(K + 1):
            sums[t] = (sums[t] + powers[t]) % MOD

    print(answer)

