    solve()

import sys


def convert_uv(u, v, off):
    return (u + v + off, u - v + off)


def replacement_candidates(a, d):
    ar, ac = a
    dr, dc = d
    result = []

    # X is an orthogonal common neighbor of A and D.
    for xr, xc in ((ar + 1, ac), (ar - 1, ac),
                   (ar, ac + 1), (ar, ac - 1)):
        if abs(xr - dr) + abs(xc - dc) != 1:
            continue
        # Y is an orthogonal neighbor of X and diagonally adjacent to D.
        for yr, yc in ((xr + 1, xc), (xr - 1, xc),
                       (xr, xc + 1), (xr, xc - 1)):
            if abs(yr - dr) == 1 and abs(yc - dc) == 1:
                if (yr, yc) != a:
                    result.append(((xr, xc), (yr, yc)))
    return result


def solve_case(R, B):
    if R & 1:
        return None

    off = 300000

    if B == 0:
        if R == 2:
            pts = [(0, 0), (1, 0)]
        else:
            a = 1
            b = R // 2 - 1
            pts = []

            for x in range(a + 1):
                pts.append((x, 0))
            for y in range(1, b + 1):
                pts.append((a, y))
            for x in range(a - 1, -1, -1):
                pts.append((x, b))
            for y in range(b - 1, 0, -1):
                pts.append((0, y))

        ans = []
        for r, c in pts:
            ans.append(("R", r + off, c + off))
        return ans

    points = []
    labels = []

    if B & 1:
        # Core R-R-B triangle, with a blue path of length B
        # replacing the blue edge of the triangle.
        A = (0, 0)
        X = (1, 0)
        D = (1, 1)

        points = [A, X, D]
        labels = ["R", "R", "B"]

        q = (B - 1) // 2
        path_uv = []

        for v in range(1, q + 1):
            path_uv.append((1, v))
        for v in range(q, -1, -1):
            path_uv.append((0, v))

        for u, v in path_uv:
            points.append((u + v, u - v))
            labels.append("B")

        chosen_edge = 2
    else:
        if B == 2:
            points = [(0, 0), (1, 1)]
            labels = ["B", "B"]
        else:
            a = 1
            b = B // 2 - 1
            uv = []

            for u in range(a + 1):
                uv.append((u, 0))
            for v in range(1, b + 1):
                uv.append((a, v))
            for u in range(a - 1, -1, -1):
                uv.append((u, b))
            for v in range(b - 1, 0, -1):
                uv.append((0, v))

            points = [convert_uv(u, v, 0) for u, v in uv]
            labels = ["B"] * len(points)

        chosen_edge = 0

    # Each replacement changes one B edge A->D into
    # R edge, R edge, B edge, preserving the number of blue pieces.
    need = R // 2
    occupied = set(points)

    for _ in range(need):
        found = False
        candidates_to_try = [chosen_edge]
        if len(points) > 2:
            candidates_to_try += [
                i for i, lab in enumerate(labels)
                if lab == "B" and i != chosen_edge
            ]

        for idx in candidates_to_try:
            a = points[idx]
            d = points[(idx + 1) % len(points)]

            for x, y in replacement_candidates(a, d):
                if x not in occupied and y not in occupied:
                    insert_at = idx + 1
                    points[insert_at:insert_at] = [x, y]
                    labels[insert_at:insert_at] = ["R", "R"]
                    occupied.add(x)
                    occupied.add(y)
                    chosen_edge = idx + 2
                    found = True
                    break
            if found:
                break

        if not found:
            return None

    ans = []
    for lab, (r, c) in zip(labels, points):
        ans.append((lab, r + off, c + off))
    return ans


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    t = data[0]
    pos = 1
    out = []

    for _ in range(t):
        R, B = data[pos], data[pos + 1]
        pos += 2

        ans = solve_case(R, B)
        if ans is None:
            out.append("No")
        else:
            out.append("Yes")
            out.extend(f"{p} {r} {c}" for p, r, c in ans)

    sys.stdout.write("\n".join(out))


if __name__ == "__main__":
    main()

import sys
from collections import deque

def exact_answer(a):
    start = tuple(a)
    q = deque([(start, 0)])
    seen = {start}

    while q:
        s, d = q.popleft()
        if not s:
            return d

        n = len(s)

        for i in range(n - 1):
            t = list(s)
            t[i], t[i + 1] = t[i + 1], t[i]
            t = tuple(t)
            if t not in seen:
                seen.add(t)
                q.append((t, d + 1))

        first = s[0]
        k = 0
        while k < n and s[k] == first:
            k += 1

        for length in range(1, k + 1):
            t = s[length:]
            if t not in seen:
                seen.add(t)
                q.append((t, d + 1))

def solve():
    input = sys.stdin.readline
