        if len(set(a)) == 2:
            x, y = a[0], next(v for v in a if v != a[0])
            if all(a[i] == (x if i % 2 == 0 else y) for i in range(n)):
                ans.append(str(n - 3))
                continue

        ans.append(str(n))

