from typing import List

class Solution:
    def minOperations(self, queries: List[List[int]]) -> int:
        def prefix(x: int) -> int:
            if x <= 0:
                return 0

            total = 0
            start = 1
            steps = 1

            while start <= x:
                end = min(x, start * 4 - 1)
                total += (end - start + 1) * steps
                start *= 4
                steps += 1

            return total

        result = 0

        for left, right in queries:
            required = prefix(right) - prefix(left - 1)
            result += (required + 1) // 2

        return result

import sys

def solve():
    input = sys.stdin.readline

    N, R, C = map(int, input().split())
    S = input().strip()

    r = c = 0
    visited = {(0, 0)}
    answer = []

    for ch in S:
        if ch == 'N':
            r -= 1
        elif ch == 'S':
            r += 1
        elif ch == 'W':
            c -= 1
        else:  # E
            c += 1

        if (r - R, c - C) in visited:
            answer.append('1')
        else:
            answer.append('0')

        visited.add((r, c))

    print(''.join(answer))

