class Solution:
    def beautifulNumbers(self, l: int, r: int) -> int:
        def count_no_zero(n: int) -> int:
            if n <= 0:
                return 0

            digits = list(map(int, str(n)))
            length = len(digits)

            count = sum(9 ** k for k in range(1, length))

            for i, limit in enumerate(digits):
                remaining = length - i - 1
                count += max(0, limit - 1) * (9 ** remaining)

                if limit == 0:
                    return count

            return count + 1

        def count_beautiful_no_zero(n: int) -> int:
            if n <= 0:
                return 0

            digits = list(map(int, str(n)))
            length = len(digits)
            result = 0

            for target_sum in range(1, 9 * length + 1):
                modulus = target_sum

                # Count valid numbers with fewer digits than n.
                dp = {(0, 1 % modulus): 1}

                for used_length in range(1, length):
                    next_dp = {}

                    for (digit_sum, remainder), ways in dp.items():
                        for digit in range(1, 10):
                            new_sum = digit_sum + digit
                            if new_sum >= target_sum:
                                continue

                            remaining = length - used_length
                            if new_sum + remaining > target_sum:
                                continue
                            if new_sum + 9 * remaining < target_sum:
                                continue

                            new_remainder = (remainder * digit) % modulus
                            key = (new_sum, new_remainder)
                            next_dp[key] = next_dp.get(key, 0) + ways

                    dp = next_dp
                    result += dp.get((target_sum, 0), 0)

                # Count valid numbers having the same number of digits as n.
                loose = {}
                tight = {(0, 1 % modulus): 1}

                for pos, limit in enumerate(digits):
                    remaining = length - pos - 1
                    next_loose = {}
                    next_tight = {}

                    for (digit_sum, remainder), ways in loose.items():
                        for digit in range(1, 10):
                            new_sum = digit_sum + digit
                            if new_sum >= target_sum:
                                continue
                            if new_sum + remaining > target_sum:
                                continue
                            if new_sum + 9 * remaining < target_sum:
                                continue

                            new_remainder = (remainder * digit) % modulus
                            key = (new_sum, new_remainder)
                            next_loose[key] = next_loose.get(key, 0) + ways

                    for (digit_sum, remainder), ways in tight.items():
                        for digit in range(1, limit + 1):
                            new_sum = digit_sum + digit
                            if new_sum > target_sum:
                                continue
                            if new_sum + remaining < target_sum:
                                continue
                            if new_sum + 9 * remaining > target_sum:
                                continue

                            new_remainder = (remainder * digit) % modulus
                            key = (new_sum, new_remainder)

                            if digit == limit:
                                next_tight[key] = next_tight.get(key, 0) + ways
                            else:
                                next_loose[key] = next_loose.get(key, 0) + ways

                    loose = next_loose
                    tight = next_tight

                result += loose.get((target_sum, 0), 0)
                result += tight.get((target_sum, 0), 0)

            return result

        def count_up_to(n: int) -> int:
            if n <= 0:
                return 0

            no_zero = count_no_zero(n)
            beautiful_without_zero = count_beautiful_no_zero(n)

            # Every number containing a zero digit is automatically beautiful.
            return (n - no_zero) + beautiful_without_zero

        return count_up_to(r) - count_up_to(l - 1)

