    n = int(input())
    p = list(map(int, input().split()))

    bit = FenwickTree(n)
    answer = 0

    for j, x in enumerate(p, 1):
        not_greater = bit.sum(x)
        greater = (j - 1) - not_greater

        answer += greater * (2 * j - greater - 1) // 2
        bit.add(x, 1)

    print(answer)


