def normalize(s, x, y):
    stack = []

    def add_run(ch, length):
        if length == 0:
            return

        if stack and stack[-1][0] == ch:
            stack[-1] = (ch, stack[-1][1] + length)
        else:
            stack.append((ch, length))

        if ch != 1 or len(stack) < 2:
            return
        if stack[-2][0] != 0:
            return

        carry = 0

        while len(stack) >= 2 and stack[-2][0] == 0 and stack[-1][0] == 1:
            a = stack.pop()[1]
            b = stack.pop()[1]

            if a < x or b < y:
                stack.append((0, a))
                stack.append((1, b))
                break

            q, rem = divmod(a, x)

            if rem:
                stack.append((0, rem))
                stack.append((1, b))
                carry = q * x
                break
            else:
                # The new one-run may merge with the previous one-run,
                # exposing another reducible boundary to its left.
                if stack and stack[-1][0] == 1:
                    stack[-1] = (1, stack[-1][1] + b)
                else:
                    stack.append((1, b))
                carry = q * x

        if carry:
            if stack and stack[-1][0] == 0:
                stack[-1] = (0, stack[-1][1] + carry)
            else:
                stack.append((0, carry))

    start = 0
    for i in range(1, len(s) + 1):
        if i == len(s) or s[i] != s[start]:
            add_run(0 if s[start] == '0' else 1, i - start)
            start = i

    return stack


