class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        by_right = [[] for _ in range(n + 1)]
        m = len(conflictingPairs)

        for i, (a, b) in enumerate(conflictingPairs):
            if a > b:
                a, b = b, a
            by_right[b].append((a, i))

        gains = [0] * m
        total = 0

        max_a = 0
        second_a = 0
        max_id = -1

        for right in range(1, n + 1):
            for a, idx in by_right[right]:
                if a > max_a:
                    second_a = max_a
                    max_a = a
                    max_id = idx
                elif a > second_a:
                    second_a = a

            total += right - max_a

            if max_id != -1:
                gains[max_id] += max_a - second_a

        return total + max(gains)

