class Solution:
    def generateString(self, str1: str, str2: str) -> str:
        n = len(str1)
        m = len(str2)
        length = n + m - 1

        chars = [None] * length

        # Apply all mandatory ("T") occurrences.
        for start in range(n):
            if str1[start] == 'T':
                for j, ch in enumerate(str2):
                    pos = start + j
                    if chars[pos] is not None and chars[pos] != ch:
                        return ""
                    chars[pos] = ch

        # For each forbidden window, determine its last unfixed position.
        # Such a window must differ from str2 at or before that position.
        buckets = [[] for _ in range(length)]
        initially_mismatched = [False] * n

        for start in range(n):
            if str1[start] != 'F':
                continue

            last_free = -1
            mismatched = False

            for j in range(m):
                pos = start + j
                if chars[pos] is None:
                    last_free = pos
                elif chars[pos] != str2[j]:
                    mismatched = True

            initially_mismatched[start] = mismatched

            if last_free == -1:
                if not mismatched:
                    return ""
            else:
                buckets[last_free].append((start, str2[last_free - start]))

        # Greedily assign remaining positions from left to right.
        for pos in range(length):
            if chars[pos] is None:
                forbidden = set()

                # If this is the last free position of an active forbidden
                # window, matching str2 here would make that window invalid.
                for start, required in buckets[pos]:
                    if not initially_mismatched[start]:
                        forbidden.add(required)

                for code in range(ord('a'), ord('z') + 1):
                    ch = chr(code)
                    if ch not in forbidden:
                        chars[pos] = ch
                        break
                else:
                    return ""

                # Mark forbidden windows that have now been made different.
                lo = max(0, pos - m + 1)
                hi = min(n - 1, pos)
                for start in range(lo, hi + 1):
                    if str1[start] == 'F' and not initially_mismatched[start]:
                        if chars[pos] != str2[pos - start]:
                            initially_mismatched[start] = True

        return ''.join(chars)

