from math import factorial


class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        odd_count = (n + 1) // 2
        even_count = n // 2

        def count_completions(remaining_odd: int, remaining_even: int,
                              next_parity: int) -> int:
            length = remaining_odd + remaining_even
            if length == 0:
                return 1

            needed_next = (length + 1) // 2
            needed_other = length // 2

            if next_parity == 1:
                if remaining_odd != needed_next or remaining_even != needed_other:
                    return 0
            else:
                if remaining_even != needed_next or remaining_odd != needed_other:
                    return 0

            return factorial(remaining_odd) * factorial(remaining_even)

        total = 0
        for value in range(1, n + 1):
            if value % 2 == 1:
                total += count_completions(odd_count - 1, even_count, 0)
            else:
                total += count_completions(odd_count, even_count - 1, 1)

        if k > total:
            return []

        remaining = list(range(1, n + 1))
        result = []
        remaining_odd = odd_count
        remaining_even = even_count
        previous_parity = None

        while remaining:
            for i, value in enumerate(remaining):
                parity = value % 2

                if previous_parity is not None and parity == previous_parity:
                    continue

                next_odd = remaining_odd - (parity == 1)
                next_even = remaining_even - (parity == 0)

                if remaining_odd + remaining_even == 1:
                    ways = 1
                else:
                    ways = count_completions(
                        next_odd,
                        next_even,
                        1 - parity
                    )

                if k > ways:
                    k -= ways
                else:
                    result.append(value)
                    remaining.pop(i)
                    remaining_odd = next_odd
                    remaining_even = next_even
                    previous_parity = parity
                    break

        return result

