from typing import List


class Solution:
    def maxDistance(self, side: int, points: List[List[int]], k: int) -> int:
        perimeter = 4 * side
        positions = []

        for x, y in points:
            if y == 0:
                pos = x
            elif x == side:
                pos = side + y
            elif y == side:
                pos = 3 * side - x
            else:
                pos = 4 * side - y
            positions.append(pos)

        positions.sort()
        n = len(positions)
        doubled = positions + [p + perimeter for p in positions]

        def feasible(distance: int) -> bool:
            nxt = [2 * n] * (2 * n)

            for i in range(2 * n):
                nxt[i] = bisect_left(
                    doubled, doubled[i] + distance, i + 1, 2 * n
                )

            for start in range(n):
                cur = start
                for _ in range(k - 1):
                    cur = nxt[cur]
                    if cur >= start + n:
                        break
                else:
                    if doubled[cur] <= doubled[start] + perimeter - distance:
                        return True

            return False

        low, high = 0, side + 1

        while low + 1 < high:
            mid = (low + high) // 2
            if feasible(mid):
                low = mid
            else:
                high = mid

        return low

