    n = data[0]
    adj = [[] for _ in range(n)]

    idx = 1
    for _ in range(n - 1):
        a = data[idx] - 1
        b = data[idx + 1] - 1
        idx += 2
        adj[a].append(b)
        adj[b].append(a)

    parent = [-1] * n
    order = [0]
    parent[0] = -2

    for u in order:
        for v in adj[u]:
            if v == parent[u]:
                continue
            parent[v] = u
            order.append(v)

    # down[u] = best branch size starting at u and going away from parent[u]
    down = [1] * n

    for u in reversed(order):
        vals = []
        for v in adj[u]:
            if parent[v] == u:
                vals.append(down[v])

        if len(vals) >= 3:
            vals.sort(reverse=True)
            down[u] = 1 + vals[0] + vals[1] + vals[2]
        else:
            down[u] = 1

    # up[u] = best branch size starting at parent[u] and entering u
    up = [1] * n
    answer = -1

    for u in order:
        incoming = []

        if parent[u] >= 0:
            incoming.append((up[u], parent[u]))

        for v in adj[u]:
            if parent[v] == u:
                incoming.append((down[v], v))

        incoming.sort(reverse=True)

        if len(incoming) >= 4:
            answer = max(answer, 1 + sum(value for value, _ in incoming[:4]))

        for v in adj[u]:
            if parent[v] != u:
                continue

            total = 0
            count = 0

            for value, neighbor in incoming:
                if neighbor == v:
                    continue
                total += value
                count += 1
                if count == 3:
                    break

            up[v] = 1 + total if count == 3 else 1

    print(answer)

