import heapq


def solve():
    input = sys.stdin.readline
    n = int(input())
    grid = [input().strip() for _ in range(n)]

    INF = 10**18
    dist = [[INF] * n for _ in range(n)]

    incoming = [[[] for _ in range(n)] for _ in range(26)]
    outmask = [[0] * n for _ in range(26)]

    for i in range(n):
        for j, ch in enumerate(grid[i]):
            if ch != '-':
                c = ord(ch) - 97
                incoming[c][j].append(i)
                outmask[c][i] |= 1 << j

    transitions = [[] for _ in range(n)]
    for x in range(n):
        for c in range(26):
            if incoming[c][x]:
                transitions[x].append((incoming[c][x], c))

    dijkstra_heap = []
    removal_heap = []

    def set_distance(i, j, value):
        if value < dist[i][j]:
            dist[i][j] = value
            heapq.heappush(dijkstra_heap, (value, i, j))
            heapq.heappush(removal_heap, (value, i, j))

    for i in range(n):
        set_distance(i, i, 0)

    for i in range(n):
        for j, ch in enumerate(grid[i]):
            if ch != '-' and i != j:
                set_distance(i, j, 1)

    all_bits = (1 << n) - 1
    bad = [all_bits] * n

    current_threshold = -1

    while dijkstra_heap:
        d, x, y = heapq.heappop(dijkstra_heap)
        if dist[x][y] != d:
            continue

        threshold = d + 2

        while removal_heap and removal_heap[0][0] <= threshold:
            value, u, v = heapq.heappop(removal_heap)
            if dist[u][v] == value:
                bad[u] &= ~(1 << v)

        current_threshold = threshold

        for vertices, c in transitions[x]:
            mask = outmask[c][y]
            if mask == 0:
                continue

            for u in vertices:
                candidates = bad[u] & mask
                while candidates:
                    bit = candidates & -candidates
                    candidates -= bit
                    v = bit.bit_length() - 1

                    dist[u][v] = threshold
                    bad[u] &= ~bit
                    heapq.heappush(dijkstra_heap, (threshold, u, v))
                    heapq.heappush(removal_heap, (threshold, u, v))

    output = []
    for i in range(n):
        row = []
        for j in range(n):
            row.append(str(dist[i][j] if dist[i][j] < INF else -1))
        output.append(" ".join(row))

    sys.stdout.write("\n".join(output))


if __name__ == "__main__":
    solve()

