class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n = len(grid)
        m = len(grid[0])
        size = n * m

        # Clockwise order:
        # southeast -> southwest -> northwest -> northeast -> southeast
        directions = [(1, 1), (1, -1), (-1, -1), (-1, 1)]

        def next_value(value: int) -> int:
            if value == 1:
                return 2
            return 0 if value == 2 else 2

        # straight[d][expected][index] =
        # length of a valid straight segment starting at index,
        # assuming the current cell must equal expected.
        straight = [
            [array("H", [0]) * size for _ in range(3)]
            for _ in range(4)
        ]

        for d, (dr, dc) in enumerate(directions):
            row_range = range(n - 1, -1, -1) if dr == 1 else range(n)
            col_range = range(m - 1, -1, -1) if dc == 1 else range(m)

            for r in row_range:
                nr = r + dr
                for c in col_range:
                    idx = r * m + c
                    cell = grid[r][c]

                    if 0 <= nr < n:
                        nc = c + dc
                        if 0 <= nc < m:
                            nidx = nr * m + nc
                            for expected in (0, 1, 2):
                                if cell == expected and grid[nr][nc] == next_value(expected):
                                    straight[d][expected][idx] = (
                                        1 + straight[d][next_value(expected)][nidx]
                                    )

        # best[d][expected][index] =
        # maximum length from this cell in direction d, with at most
        # one clockwise turn remaining.
        best = [
            [array("H", [0]) * size for _ in range(3)]
            for _ in range(4)
        ]

        answer = 0

        for d, (dr, dc) in enumerate(directions):
            turn_d = (d + 1) % 4
            tdr, tdc = directions[turn_d]

            row_range = range(n - 1, -1, -1) if dr == 1 else range(n)
            col_range = range(m - 1, -1, -1) if dc == 1 else range(m)

            for r in row_range:
                nr = r + dr
                for c in col_range:
                    idx = r * m + c
                    cell = grid[r][c]

                    if cell == 1:
                        answer = max(answer, 1)

                    if not (0 <= nr < n):
                        continue

                    nc = c + dc
                    if not (0 <= nc < m):
                        continue

                    nidx = nr * m + nc

                    tr = r + tdr
                    tc = c + tdc
                    turn_exists = 0 <= tr < n and 0 <= tc < m
                    tidx = tr * m + tc if turn_exists else -1

                    for expected in (0, 1, 2):
                        if cell != expected:
                            continue

                        following = next_value(expected)
                        no_turn = best[d][following][nidx]

                        turn = 0
                        if turn_exists:
                            turn = straight[turn_d][following][tidx]

                        best[d][expected][idx] = 1 + max(no_turn, turn)

                        if expected == 1:
                            answer = max(answer, best[d][expected][idx])

        return answer

