class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        a, b, c = p.split("*")
        n = len(s)

        def find_occurrences(pattern: str):
            if not pattern:
                return []

            m = len(pattern)
            lps = [0] * m
            j = 0

            for i in range(1, m):
                while j and pattern[i] != pattern[j]:
                    j = lps[j - 1]
                if pattern[i] == pattern[j]:
                    j += 1
                lps[i] = j

            occurrences = []
            j = 0
            for i, ch in enumerate(s):
                while j and ch != pattern[j]:
                    j = lps[j - 1]
                if ch == pattern[j]:
                    j += 1
                if j == m:
                    occurrences.append(i - m + 1)
                    j = lps[j - 1]

            return occurrences

        occ_a = find_occurrences(a)
        occ_b = find_occurrences(b)
        occ_c = find_occurrences(c)

        starts = range(n + 1) if not a else occ_a
        answer = n + 1

        for start in starts:
            after_a = start + len(a)

            if b:
                idx_b = bisect_left(occ_b, after_a)
                if idx_b == len(occ_b):
                    continue
                b_start = occ_b[idx_b]
                after_b = b_start + len(b)
            else:
                after_b = after_a

            if c:
                idx_c = bisect_left(occ_c, after_b)
                if idx_c == len(occ_c):
                    continue
                end = occ_c[idx_c] + len(c)
            else:
                end = after_b

            answer = min(answer, end - start)

        return -1 if answer == n + 1 else answer

