import sys

MOD = 998244353


def factorize(x):
    res = {}
    d = 2
    while d * d <= x:
        while x % d == 0:
            res[d] = res.get(d, 0) + 1
            x //= d
        d += 1
    if x > 1:
        res[x] = res.get(x, 0) + 1
    return res


def solve():
    input = sys.stdin.readline
    n = int(input())
    a = list(map(int, input().split()))

    factors = [factorize(x) for x in a]
    primes = set()
    for f in factors:
        primes.update(f.keys())

    answer = 1

    for p in primes:
        exps = [f.get(p, 0) for f in factors]
        total = sum(exps)
        max_exp = max(exps)

        powers = [1] * (max(total, max_exp * n) + 1)
        pm = p % MOD
        for i in range(1, len(powers)):
            powers[i] = powers[i - 1] * pm % MOD

        # L[t]: weighted sum of prefixes whose first occurrence
        # of the minimum is at position t.
        left = [0] * n
        left[0] = 1

        dp = [0] * (total + 1)
        dp[0] = 1

        for i, e in enumerate(exps):
            ndp = [0] * (total + 1)

            if e == 0:
                for h, val in enumerate(dp):
                    if val:
                        ndp[h] = val * powers[h] % MOD
            else:
                drop_factor_base = i + 1  # number of existing positions

                for h, val in enumerate(dp):
                    if not val:
                        continue

                    # Next height is h + e.
                    nh = h + e
                    if nh <= total:
                        ndp[nh] = (ndp[nh] + val * powers[nh]) % MOD

                    # Next height is h - e.
                    if h >= e:
                        nh = h - e
                        ndp[nh] = (ndp[nh] + val * powers[nh]) % MOD
                    else:
                        # A new strict minimum is created.
                        drop = e - h
                        left[i + 1] = (
                            left[i + 1]
                            + val * powers[drop * drop_factor_base]
                        ) % MOD
                        ndp[0] = (ndp[0] + val * powers[drop * drop_factor_base]) % MOD

            dp = ndp

        # R[t]: weighted sum of suffixes starting from height zero at t,
        # never going below zero.
        right = [0] * n
        g = [1] * (total + 1)  # g for position n

        if n == 1:
            right[0] = 1
        else:
            for i in range(n - 2, -1, -1):
                e = exps[i]
                ng = [0] * (total + 1)

                if e == 0:
                    for h in range(total + 1):
                        ng[h] = g[h] * powers[h] % MOD
                else:
                    for h in range(total + 1):
                        val = 0

                        nh = h + e
                        if nh <= total:
                            val += g[nh] * powers[nh]

                        if h >= e:
                            nh = h - e
                            val += g[nh] * powers[nh]

                        ng[h] = val % MOD

                g = ng
                right[i] = g[0]

            right[n - 1] = 1

        contribution = 0
        for l, r in zip(left, right):
            contribution = (contribution + l * r) % MOD

        answer = answer * contribution % MOD

    print(answer)


