class Solution:
    def countSubstrings(self, s: str) -> int:
        moduli = (3, 7, 9)
        inverses = {3: 1, 7: 5, 9: 1}

        remainder = {m: 0 for m in moduli}
        inverse_power = {m: 1 for m in moduli}
        counts = {m: [0] * m for m in moduli}

        for m in moduli:
            counts[m][0] = 1

        ans = 0

        for i, ch in enumerate(s):
            d = ord(ch) - ord('0')

            for m in moduli:
                remainder[m] = (
                    remainder[m] + d * inverse_power[m]
                ) % m
                inverse_power[m] = (
                    inverse_power[m] * inverses[m]
                ) % m

            if d == 0:
                pass
            elif d in (1, 2, 5):
                ans += i + 1
            elif d in (3, 6, 9):
                m = 3 if d in (3, 6) else 9
                ans += counts[m][remainder[m]]
            elif d == 7:
                ans += counts[7][remainder[7]]
            elif d == 4:
                ans += 1
                if i >= 1:
                    prev = ord(s[i - 1]) - ord('0')
                    if (10 * prev + d) % 4 == 0:
                        ans += i
            elif d == 8:
                ans += 1

                if i >= 1:
                    prev = ord(s[i - 1]) - ord('0')
                    if (10 * prev + d) % 8 == 0:
                        ans += 1

                if i >= 2:
                    prev = ord(s[i - 1]) - ord('0')
                    prev_prev = ord(s[i - 2]) - ord('0')
                    if (100 * prev_prev + 10 * prev + d) % 8 == 0:
                        ans += i - 1

            for m in moduli:
                counts[m][remainder[m]] += 1

        return ans

