class Solution:
    def maxScore(self, points: List[int], m: int) -> int:
        n = len(points)

        def can(target: int) -> bool:
            required = [(target + p - 1) // p for p in points]

            moves = 1  # First move: -1 -> 0
            current = 1  # Visits to index 0
            next_prefilled = 0

            for i in range(n - 1):
                if current < required[i]:
                    extra = required[i] - current
                    moves += 2 * extra
                    next_prefilled += extra
                    if moves > m:
                        return False

                # At the second-last index, decide whether entering the last
                # index is necessary.
                if i == n - 2:
                    if next_prefilled >= required[i + 1]:
                        return moves <= m

                    moves += 1  # Move to the last index
                    current_last = next_prefilled + 1

                    if current_last < required[i + 1]:
                        extra = required[i + 1] - current_last
                        moves += 2 * extra

                    return moves <= m

                # Move from index i to index i + 1.
                moves += 1
                if moves > m:
                    return False

                current = next_prefilled + 1
                next_prefilled = 0

            return True

        low = 0
        high = min(points) * m + 1

        while low + 1 < high:
            mid = (low + high) // 2
            if can(mid):
                low = mid
            else:
                high = mid

        return low

