    state_count = 1 << N
    transitions = [[0] * 26 for _ in range(state_count)]

    for mask in range(state_count):
        old = [0] * (N + 1)
        for i in range(1, N + 1):
            old[i] = old[i - 1] + ((mask >> (i - 1)) & 1)

        for c in range(26):
            new_mask = 0
            prev_new = 0

            for i in range(1, N + 1):
                best = max(
                    old[i],
                    prev_new,
                    old[i - 1] + (ord(S[i - 1]) - 97 == c)
                )
                if best > prev_new:
                    new_mask |= 1 << (i - 1)
                prev_new = best

            transitions[mask][c] = new_mask

    dp = [0] * state_count
    dp[0] = 1

    for _ in range(M):
        ndp = [0] * state_count
        for mask, count in enumerate(dp):
            if count == 0:
                continue
            for c in range(26):
                nxt = transitions[mask][c]
                ndp[nxt] = (ndp[nxt] + count) % MOD
        dp = ndp

    ans = [0] * (N + 1)
    for mask, count in enumerate(dp):
        ans[mask.bit_count()] = (ans[mask.bit_count()] + count) % MOD

    print(*ans)

