class Solution:
    def distanceSum(self, m: int, n: int, k: int) -> int:
        MOD = 10**9 + 7
        total_cells = m * n

        factorial = [1] * (total_cells - 1)
        for i in range(1, total_cells - 1):
            factorial[i] = factorial[i - 1] * i % MOD

        inv_factorial = [1] * (total_cells - 1)
        inv_factorial[-1] = pow(factorial[-1], MOD - 2, MOD)
        for i in range(total_cells - 2, 0, -1):
            inv_factorial[i - 1] = inv_factorial[i] * i % MOD

        def comb(a: int, b: int) -> int:
            if b < 0 or b > a:
                return 0
            return (
                factorial[a]
                * inv_factorial[b]
                % MOD
                * inv_factorial[a - b]
                % MOD
            )

        row_distance_sum = m * (m - 1) * (m + 1) // 6
        col_distance_sum = n * (n - 1) * (n + 1) // 6

        total_pair_distance = (
            n * n * row_distance_sum
            + m * m * col_distance_sum
        ) % MOD

        arrangements_per_pair = comb(total_cells - 2, k - 2)

        return total_pair_distance * arrangements_per_pair % MOD

