def mat_mul(a, b, mod):
    n = len(a)
    res = [[0] * n for _ in range(n)]
    for i in range(n):
        row = res[i]
        ai = a[i]
        for k, x in enumerate(ai):
            if x:
                bk = b[k]
                for j in range(n):
                    row[j] += x * bk[j]
        for j in range(n):
            row[j] %= mod
    return res


def mat_pow(a, e, mod):
    n = len(a)
    result = [[0] * n for _ in range(n)]
    for i in range(n):
        result[i][i] = 1

    while e:
        if e & 1:
            result = mat_mul(result, a, mod)
        a = mat_mul(a, a, mod)
        e >>= 1
    return result


def main():
    input = sys.stdin.readline
