    if p == 2:
        value = n % 2
        for _ in range(n):
            print(" ".join([str(value)] * n))
        return

    zero_count = sum(row.count(0) for row in a)
    sign = 1 if zero_count % 2 == 0 else p - 1

    c = [row[:] for row in a]
    for i in range(n):
        for j in range(n):
            if c[i][j] == 0:
                c[i][j] = 0

    result = mat_pow(c, p, p)

    if p == 3:
        # Additional surviving walks use one zero off-diagonal entry twice
        # and the reverse fixed entry once.
        for i in range(n):
            for j in range(n):
                if i != j and a[i][j] == 0:
                    result[i][j] = (result[i][j] + a[j][i]) % p

    for i in range(n):
        print(" ".join(str((sign * result[i][j]) % p) for j in range(n)))


