class Solution:
    def maximumWeight(self, intervals: List[List[int]]) -> List[int]:
        ordered = sorted(
            enumerate(intervals),
            key=lambda x: (x[1][1], x[1][0], x[0])
        )
        ends = [interval[1][1] for _, interval in ordered]
        n = len(ordered)
        neg_inf = -10**30

        scores = [[0] for _ in range(5)]
        choices = [[()] for _ in range(5)]

        for i, (idx, interval) in enumerate(ordered, 1):
            left, right, weight = interval
            prev_count = bisect_left(ends, left)

            scores[0].append(0)
            choices[0].append(())

            for count in range(1, 5):
                skip_score = scores[count][i - 1]
                skip_choice = choices[count][i - 1]

                base_score = scores[count - 1][prev_count]
                if base_score == neg_inf:
                    take_score = neg_inf
                    take_choice = None
                else:
                    take_score = base_score + weight
                    previous = choices[count - 1][prev_count]
                    take_choice = tuple(sorted(previous + (idx,)))

                if take_score > skip_score:
                    scores[count].append(take_score)
                    choices[count].append(take_choice)
                elif take_score < skip_score:
                    scores[count].append(skip_score)
                    choices[count].append(skip_choice)
                else:
                    if skip_choice is None or (
                        take_choice is not None and take_choice < skip_choice
                    ):
                        scores[count].append(take_score)
                        choices[count].append(take_choice)
                    else:
                        scores[count].append(skip_score)
                        choices[count].append(skip_choice)

        best_score = neg_inf
        best_choice = None

        for count in range(5):
            score = scores[count][n]
            choice = choices[count][n]
            if score > best_score or (
                score == best_score and
                (best_choice is None or choice < best_choice)
            ):
                best_score = score
                best_choice = choice

        return list(best_choice)

