class Solution:
    def minLength(self, s: str, numOps: int) -> int:
        n = len(s)

        def feasible(limit: int) -> bool:
            inf = n + 1
            dp0 = [inf] * (limit + 1)
            dp1 = [inf] * (limit + 1)

            dp0[1] = 0 if s[0] == '0' else 1
            dp1[1] = 0 if s[0] == '1' else 1

            for ch in s[1:]:
                ndp0 = [inf] * (limit + 1)
                ndp1 = [inf] * (limit + 1)

                best0 = min(dp0)
                best1 = min(dp1)

                ndp0[1] = best1 + (ch != '0')
                ndp1[1] = best0 + (ch != '1')

                cost0 = ch != '0'
                cost1 = ch != '1'

                for length in range(1, limit):
                    if dp0[length] + cost0 < ndp0[length + 1]:
                        ndp0[length + 1] = dp0[length] + cost0
                    if dp1[length] + cost1 < ndp1[length + 1]:
                        ndp1[length + 1] = dp1[length] + cost1

                dp0, dp1 = ndp0, ndp1

            return min(min(dp0), min(dp1)) <= numOps

        left, right = 1, n
        while left < right:
            mid = (left + right) // 2
            if feasible(mid):
                right = mid
            else:
                left = mid + 1

        return left

class Solution:
    def makeStringGood(self, s: str) -> int:
        cnt = [0] * 26
        for ch in s:
            cnt[ord(ch) - 97] += 1

        n = len(s)
        candidates = {1}
        for v in cnt:
            if v > 0:
                candidates.add(v)
                if v > 1:
                    candidates.add(v - 1)
                candidates.add(v + 1)

        max_count = max(cnt)
        candidates = [k for k in candidates if 1 <= k <= max_count]
        if not candidates:
            return n

        INF = 10**18
        answer = n

        for k in candidates:
            # dp0[x]: minimum cost after processing the prefix,
            # with x characters carried to the next letter and no
            # positive-frequency letter selected yet.
            # dp1[x]: same, but at least one letter has been selected.
            dp0 = [INF] * (k + 1)
            dp1 = [INF] * (k + 1)
            dp0[0] = 0

            for a in cnt:
                ndp0 = [INF] * (k + 1)
                ndp1 = [INF] * (k + 1)

                for carried in range(k + 1):
                    base0 = dp0[carried]
                    base1 = dp1[carried]
                    if base0 == INF and base1 == INF:
                        continue

                    total = a + carried

                    # Do not use this letter in the final string.
                    nxt = min(total, k)
                    cost = total

                    if base0 + cost < ndp0[nxt]:
                        ndp0[nxt] = base0 + cost
                    if base1 + cost < ndp1[nxt]:
                        ndp1[nxt] = base1 + cost

                    # Use this letter with final frequency k.
                    if total < k:
                        nxt = 0
                        cost = k - total
                    else:
                        nxt = min(total - k, k)
                        cost = total - k

                    if base0 + cost < ndp1[nxt]:
                        ndp1[nxt] = base0 + cost
                    if base1 + cost < ndp1[nxt]:
                        ndp1[nxt] = base1 + cost

                dp0, dp1 = ndp0, ndp1

            best = min(dp1[x] + x for x in range(k + 1))
            answer = min(answer, best)

        return answer

