def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n = data[0]
    a = data[1:]

    total_sum = sum(a)
    answer = (n + 1) * total_sum
    max_sum = 2 * max(a)

    mod = 2
    while mod <= max_sum:
        groups = {}

        for value in a:
            r = value % mod
            if r in groups:
                count, s = groups[r]
                groups[r] = (count + 1, s + value)
            else:
                groups[r] = (1, value)

        divisible_sum = 0

        for r, (count, s) in groups.items():
            complement = (-r) % mod
            if complement not in groups or r > complement:
                continue

            count2, s2 = groups[complement]

            if r == complement:
                divisible_sum += (count + 1) * s
            else:
                divisible_sum += s * count2 + s2 * count

        answer -= divisible_sum // mod
        mod <<= 1

    print(answer)

