    B = list(map(int, input().split()))
    P = [v - 1 for v in map(int, input().split())]
    Q = [v - 1 for v in map(int, input().split())]
    X -= 1

    def build_sequence(perm, balls):
        inv = [0] * N
        for i, v in enumerate(perm):
            inv[v] = i

        cycle_nodes = []
        cur = inv[X]
        while cur != X:
            cycle_nodes.append(cur)
            cur = inv[cur]

        cycle_set = set(cycle_nodes)
        for i, v in enumerate(balls):
            if v and i != X and i not in cycle_set:
                return None

        max_dist = 0
        for dist, node in enumerate(cycle_nodes, 1):
            if balls[node]:
                max_dist = dist

        # Required order is from the farthest node toward X.
        return cycle_nodes[:max_dist][::-1]

    red_seq = build_sequence(P, A)
    blue_seq = build_sequence(Q, B)

    if red_seq is None or blue_seq is None:
        print(-1)
        return

    if not red_seq:
        print(len(blue_seq))
