    blue_pos = {node: i for i, node in enumerate(blue_seq)}
    values = [blue_pos[node] for node in red_seq if node in blue_pos]

    lis = []
    for v in values:
        pos = bisect_left(lis, v)
        if pos == len(lis):
            lis.append(v)
        else:
            lis[pos] = v

